			dw p_filesystem_open_c, str23, lit_1
			dw kw_vtov, var_filesystem_open_open, var_h

			; main.bas 46: Do While Not FileSystem.Eof(h)
do7_t:
			dw p_filesystem_eof_c, var_h
			dw kw_vtov, var_filesystem_eof_eof, tmp0
