			pop hl			; name
			ld de, var_filesystem_open_name
			ld b, 255
p_filesystem_open_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_filesystem_open_si0_e
			inc hl
			inc de
			djnz p_filesystem_open_si0
			xor a
			ld (de), a
p_filesystem_open_si0_e:
			pop hl			; mode
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_filesystem_open_mode), de
